      originalSource: "{\n  tags: ['sidebar-ignore', 'snapshot-ignore'],\n  render: args => <Stack>\n      <Drawer {...args}>\n        <DrawerTrigger>\n          <Button> Open Fullscreen - Top</Button>\n        </DrawerTrigger>\n        <DrawerContent position=\"top\" isFullScreen>\n          <DrawerHeader>\n            Fullscreen Drawer <DrawerCloseButton />\n          </DrawerHeader>\n          <DrawerBody>Fullscreen Drawer Body</DrawerBody>\n          <DrawerFooter>Fullscreen Drawer Footer</DrawerFooter>\n        </DrawerContent>\n      </Drawer>\n      <Drawer {...args}>\n        <DrawerTrigger>\n          <Button> Open Fullscreen - Right</Button>\n        </DrawerTrigger>\n        <DrawerContent position=\"right\" isFullScreen>\n          <DrawerHeader>\n            Fullscreen Drawer <DrawerCloseButton />\n          </DrawerHeader>\n          <DrawerBody>Fullscreen Drawer Body</DrawerBody>\n          <DrawerFooter>Fullscreen Drawer Footer</DrawerFooter>\n        </DrawerContent>\n      </Drawer>\n      <Drawer {...args}>\n        <DrawerTrigger>\n          <Button> Open Fullscreen - Bottom</Button>\n        </DrawerTrigger>\n        <DrawerContent position=\"bottom\" isFullScreen>\n          <DrawerHeader>\n            Fullscreen Drawer <DrawerCloseButton />\n          </DrawerHeader>\n          <DrawerBody>Fullscreen Drawer Body</DrawerBody>\n          <DrawerFooter>Fullscreen Drawer Footer</DrawerFooter>\n        </DrawerContent>\n      </Drawer>\n      <Drawer {...args}>\n        <DrawerTrigger>\n          <Button> Open Fullscreen - Left</Button>\n        </DrawerTrigger>\n        <DrawerContent position=\"left\" isFullScreen>\n          <DrawerHeader>\n            Fullscreen Drawer <DrawerCloseButton />\n          </DrawerHeader>\n          <DrawerBody>Fullscreen Drawer Body</DrawerBody>\n          <DrawerFooter>Fullscreen Drawer Footer</DrawerFooter>\n        </DrawerContent>\n      </Drawer>\n    </Stack>\n}",
